t=np.arange(50);calm=100+np.cumsum(.15*np.sin(t/4));crowd=calm.copy();crowd[30:]-=np.linspace(0,12,20);ax.plot(t,calm,color=ACCENT,label='uncrowded illustration');ax.plot(t,crowd,color=BAD,label='crowded-exit illustration');ax.axvline(30,color=MUTED,ls='--');ax.set_xlabel('day');ax.set_ylabel('NAV (USD, starting near 100)');ax.legend(fontsize=7);ax.set_title('Stress exits can dominate quiet-period statistics',loc='left')
